+    #[test]
+    fn git_exclude_in_linked_worktree() {
+        let td = tmpdir();
+        let git_dir = td.path().join(".shared/.git");
+        let worktree = td.path().join("worktree");
+        mkdirp(git_dir.join("info"));
+        mkdirp(git_dir.join("worktrees/linked"));
+        mkdirp(worktree.join("subdir"));
+        wfile(git_dir.join("info/exclude"), "ignored\n");
+        wfile(git_dir.join("worktrees/linked/commondir"), "../..\n");
+        wfile(
+            worktree.join(".git"),
+            &format!(
+                "gitdir: {}\n",
+                git_dir.join("worktrees/linked").display()
+            ),
+        );
+        wfile(worktree.join("ignored"), "");
+        wfile(worktree.join("kept"), "");
+        wfile(worktree.join("subdir/ignored"), "");
+        wfile(worktree.join("subdir/kept"), "");
+
+        for require_git in [false, true] {
+            for git_ignore in [false, true] {
+                for git_exclude in [false, true] {
+                    let mut builder = WalkBuilder::new(&worktree);
+                    builder
+                        .require_git(require_git)
+                        .git_ignore(git_ignore)
+                        .git_exclude(git_exclude)
+                        .git_global(false);
+                    let expected = if git_exclude {
+                        vec!["kept", "subdir", "subdir/kept"]
+                    } else {
+                        vec![
+                            "ignored",
+                            "kept",
+                            "subdir",
+                            "subdir/ignored",
+                            "subdir/kept",
