+                    };
+                    assert_paths(&worktree, &builder, &expected);
+                }
+            }
+        }
+
+        let mut builder = WalkBuilder::new(td.path());
+        builder.require_git(false).git_ignore(false).git_global(false);
+        assert_paths(
+            td.path(),
+            &builder,
+            &[
+                "worktree",
+                "worktree/kept",
+                "worktree/subdir",
+                "worktree/subdir/kept",
+            ],
+        );
+    }
+
