diff --git a/crates/ignore/src/walk.rs b/crates/ignore/src/walk.rs
index f04f53a..80f12a7 100644
--- a/crates/ignore/src/walk.rs
+++ b/crates/ignore/src/walk.rs
@@ -2360,6 +2360,86 @@ mod tests {
         );
     }

+    #[test]
+    fn git_exclude_linked_worktree() {
+        let td = tmpdir();
+        let git_dir = td.path().join("main/.git");
+        let private_dir = git_dir.join("worktrees/linked");
+        let search = td.path().join("search");
+        let worktree = search.join("linked");
+        mkdirp(git_dir.join("info"));
+        mkdirp(&private_dir);
+        mkdirp(worktree.join("sub"));
+        wfile(git_dir.join("info/exclude"), "ignored\n");
+        wfile(
+            worktree.join(".git"),
+            &format!("gitdir: {}\n", private_dir.display()),
+        );
+        wfile(worktree.join("ignored"), "");
+        wfile(worktree.join("keep"), "");
+        wfile(worktree.join("sub/ignored"), "");
+        wfile(worktree.join("sub/keep"), "");
+
+        for commondir in ["../..".to_string(), git_dir.display().to_string()] {
+            wfile(private_dir.join("commondir"), &commondir);
+            for require_git in [true, false] {
+                let mut builder = WalkBuilder::new(&worktree);
+                builder
+                    .parents(false)
+                    .git_global(false)
+                    .git_ignore(false)
+                    .require_git(require_git)
+                    .git_exclude(false);
+                assert_paths(
+                    &worktree,
+                    &builder,
+                    &["ignored", "keep", "sub", "sub/ignored", "sub/keep"],
+                );
+                builder.git_exclude(true);
+                assert_paths(
+                    &worktree,
+                    &builder,
+                    &["keep", "sub", "sub/keep"],
+                );
+
+                let mut builder = WalkBuilder::new(&search);
+                builder
+                    .parents(false)
+                    .git_global(false)
+                    .git_ignore(false)
+                    .require_git(require_git);
+                assert_paths(
+                    &search,
+                    &builder,
+                    &["linked", "linked/keep", "linked/sub", "linked/sub/keep"],
+                );
+            }
+        }
+    }
+
+    #[test]
+    fn git_exclude_ordinary_directory() {
+        let td = tmpdir();
+        wfile(td.path().join(".gitignore"), "ignored\n");
+        wfile(td.path().join("ignored"), "");
+        wfile(td.path().join("excluded"), "");
+        wfile(td.path().join("keep"), "");
+        let mut builder = WalkBuilder::new(td.path());
+        builder.parents(false).git_global(false).require_git(false);
+        assert_paths(td.path(), &builder, &["excluded", "keep"]);
+        builder.git_exclude(false);
+        assert_paths(td.path(), &builder, &["excluded", "keep"]);
+
+        mkdirp(td.path().join(".git/info"));
+        wfile(td.path().join(".git/info/exclude"), "excluded\n");
+        for require_git in [true, false] {
+            builder.require_git(require_git).git_exclude(true);
+            assert_paths(td.path(), &builder, &["keep"]);
+            builder.git_exclude(false);
+            assert_paths(td.path(), &builder, &["excluded", "keep"]);
+        }
+    }
+
     #[test]
     fn explicit_ignore() {
         let td = tmpdir();

